import { useState } from 'react'
import { useHistory, useParams } from 'react-router'
import { Container } from '../../../../../../components'
import PropertyPolicySummary from '../../../../../CommonContainer/PropertySummaryPage'
import { PolicyContextProvider } from '../../../../../Private/Policy/context'
import { PROPERTY_LANG } from '../../../../../Private/Property/lang'
import useDraftApi from '../../../../../Private/Property/Pages/hooks/useDraftApi'

function PropertyCustomerSummary() {
  const history = useHistory()
  const { draftId } = useParams()

  const [draftResponseData, setDraftResponseData] = useState({})
  const [draftPolicyDetails, setDraftPolicyDetails] = useState({})

  const [isConvertToPaylater, setIsConvertToPaylater] = useState(false)

  const {
    isGetDraftLoader,
    isSaveLoader,
    isCompleteDraftLoader,
    handleSaveToDraft,
    handleCompleteDraft,
  } = useDraftApi({
    draftId: draftId,
    onGetDraftDetailSuccess: (data) => {
      setDraftResponseData(data)
      setDraftPolicyDetails(data.policy_details)
    },
    onSaveSuccess: () => handleCompleteDraft(),
    onCompleteDraftSuccess: ({ policyId }) => {
      if (isConvertToPaylater) {
        history.push(`/transaction/type/${policyId}`)
        return
      }
      history.push(
        `/customer/payment/${draftResponseData?.product_key}/${policyId}`
      )
    },
  })

  const handleSubmit = () => {
    handleSaveToDraft(
      draftPolicyDetails,
      'mv_quote_summary',
      'mv_quote_summary'
    )
  }

  return (
    <Container
      title={PROPERTY_LANG.propertyInsurance}
      loader={isGetDraftLoader || isSaveLoader || isCompleteDraftLoader}
      hideBottomTabs
      showCloseIcon
      onBackClick={() => history.push(`/customer/property/${draftId}/1/form/`)}
    >
      <PropertyPolicySummary
        step="2"
        totalSteps="4"
        draftResponseData={draftResponseData}
        policyDetail={draftPolicyDetails}
        isConvertToPaylater={isConvertToPaylater}
        setIsConvertToPaylater={setIsConvertToPaylater}
        onSubmit={handleSubmit}
      />
    </Container>
  )
}

function WrappedPropertyCustomerSummary(props) {
  return (
    <PolicyContextProvider>
      <PropertyCustomerSummary {...props} />
    </PolicyContextProvider>
  )
}

export default WrappedPropertyCustomerSummary
